import{_ as l,r as t,o as u,c as r,e as p,a,s as e,d as n}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"AJAX - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[{"level":3,"title":"Как работает AJAX","slug":"как-работает-ajax","link":"#как-работает-ajax","children":[]}]},{"level":2,"title":"Обработчики","slug":"обработчики","link":"#обработчики","children":[]},{"level":2,"title":"Data attributes API","slug":"data-attributes-api","link":"#data-attributes-api","children":[{"level":3,"title":"Примеры Data Attributes API","slug":"примеры-data-attributes-api","link":"#примеры-data-attributes-api","children":[]}]},{"level":2,"title":"JavaScript API","slug":"javascript-api","link":"#javascript-api","children":[{"level":3,"title":"Примеры JavaScript API","slug":"примеры-javascript-api","link":"#примеры-javascript-api","children":[]}]},{"level":2,"title":"Вызов обработчика AJAX из компонента","slug":"вызов-обработчика-ajax-из-компонента","link":"#вызов-обработчика-ajax-из-компонента","children":[]},{"level":2,"title":"Глобальные события AJAX","slug":"глобальные-события-ajax","link":"#глобальные-события-ajax","children":[]},{"level":2,"title":"Возвращение данных из обработчика","slug":"возвращение-данных-из-обработчика","link":"#возвращение-данных-из-обработчика","children":[]},{"level":2,"title":"Перенаправление в обработчике","slug":"перенаправление-в-обработчике","link":"#перенаправление-в-обработчике","children":[]},{"level":2,"title":"Сообщения","slug":"сообщения","link":"#сообщения","children":[]}],"relativePath":"1.x/ru/cms/ajax.md","filePath":"1.x/ru/cms/ajax.md"}'),i={name:"1.x/ru/cms/ajax.md"};function d(k,s,g,h,m,v){const o=t("pre-heading"),c=t("post-heading");return u(),r("div",null,[p(o),s[0]||(s[0]=a("h1",null,"AJAX",-1)),p(c),s[1]||(s[1]=e(`<p>OctoberCMS включает в себя AJAX фреймворк, который позволяет выполнять AJAX запросы, находящиеся в <a href="./../cms/pages.html">страницах</a>, <a href="./../cms/layouts.html">шаблонах</a> или <a href="./../cms/components.html">компонентах</a>, и обновлять элементы страницы при помощи <a href="./../cms/partials.html">фрагментов</a>. Существует два способа его использования: JavaScript API и Data attributes API. Data attributes API не требует каких-либо знаний JavaScript.</p><p><a name="introduction"></a></p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>Нужно подключить jQuery, чтобы начать использовать AJAX фреймворк. После чего необходимо вставить тег <code>{% framework %}</code> на страницу или в шаблон. Он добавит необходимые JS и CSS файлы. Пример:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token punctuation">[</span>
    <span class="token string"><span class="token punctuation">&#39;</span>assets/javascript/jquery.js<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token operator">|</span>theme <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Тег <code>{% framework %}</code> имеет необязательный параметр <strong>extras</strong>, который добавляет индикатор загрузки (отображается вверху страницы).</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><a name="how-ajax-works"></a></p><h3 id="как-работает-ajax"><a href="#как-работает-ajax" class="header-anchor">#</a> Как работает AJAX</h3><p>Вы можете использовать AJAX на любой странице при помощи <strong>Data Attributes</strong> или <strong>JavaScript</strong>. Каждый запрос вызывает <strong>обработчик событий</strong> на сервере и может обновлять элементы страницы при помощи <a href="./../cms/partials.html">фрагментов</a>. AJAX запросы работают лучше всего с формами, так как данные формы автоматически отправляется на сервер. Последовательность выполнения AJAX запроса:</p><ol><li>Клиент создает AJAX запрос, передав имя обработчика и, при необходимости, дополнительные параметры серверу.</li><li>Сервер находит обработчик с таким именем и выполняет его.</li><li>Обработчик выполняет необходимую бизнес-логику и возвращает результат в переменную страницы, которая выводится в фрагменте при помощи Twig тега.</li><li>Сервер подготавливает обновленный фрагмент, который указан в параметре <code>update</code>.</li><li>Сервер отправляет ответ с содержимым фрагмента.</li><li>Framework заменяет элемент страницы ответом сервера.</li></ol><p>Ниже приведен пример калькулятора, который использует <strong>Data Attributes API</strong>. При отправке формы вызывается обработчик <a href="#ajax-handlers"><strong>onTest</strong></a>, код которого находится ниже. Результат расчета выводится в элементе <strong>#result</strong> при помощью фрагмента <strong>calcresult</strong>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onTest<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>calcresult: &#39;#result&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Calculate<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>result<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Содержимое фрагмента <strong>calcresult</strong>:</p><div class="language-twig extra-class"><pre class="language-twig"><code>The result is <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p><a name="ajax-handlers"></a></p><h2 id="обработчики"><a href="#обработчики" class="header-anchor">#</a> Обработчики</h2><p>Обработчики AJAX - PHP функции, которые могут быть определены в странице, шаблоне или внутри компонента. Они имеют название вида <code>onНазваниеОбработчика</code> и могут передавать результат на страницу. Следующий пример демонстрирует обработчик, который определен в <a href="./../cms/themes.html#php-section">PHP секции</a> страницы. Он получает два значения из формы, суммирует их и присваивает новое число переменной страницы <strong>result</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code>url <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;js&quot;</span>
layout <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;default&quot;</span>
<span class="token operator">==</span>
<span class="token keyword">function</span> <span class="token function-definition function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$value1</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$value2</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$value1</span> <span class="token operator">+</span> <span class="token variable">$value2</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token operator">==</span>
</code></pre></div><blockquote><p><strong>Примечание:</strong> Если обработчики имеют одинаковые имена, то сначала вызывается тот, который определен в странице, затем - в шаблоне, после - в компоненте.</p></blockquote><p>The <code>onInit()</code> methods found in the <a href="./layouts.html#dynamic-pages">page execution life cycle</a> can be used for defining code that always executes before an AJAX event is handled.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onInit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// This code will be executed before</span>
    <span class="token comment">// an AJAX request is handled.</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a name="data-attributes"></a></p><h2 id="data-attributes-api"><a href="#data-attributes-api" class="header-anchor">#</a> Data attributes API</h2><p>позволяет Вам использовать AJAX без JavaScript. Вы пишете меньше кода, а получаете такой же результат. Список поддерживаемых атрибутов:</p><div class="table"><table tabindex="0"><thead><tr><th>Атрибут</th><th>Описание</th></tr></thead><tbody><tr><td><strong>data-request</strong></td><td>имя AJAX обработчика.</td></tr><tr><td><strong>data-request-confirm</strong></td><td>сообщение с подтверждением. Окно показывается до того, как запрос будет отправлен. Если пользователь нажмет &quot;Отмена&quot;, то запрос не будет отправлен.</td></tr><tr><td><strong>data-request-redirect</strong></td><td>после того, как запрос будет успешно отправлен, пользователь перейдет на эту страницу.</td></tr><tr><td><strong>data-request-update</strong></td><td>список фрагментов и элементов страницы, которые нужно обновить. Пример: <code>&#39;my-partial&#39;: &#39;#selector&#39;, &#39;partial&#39;: &#39;@#selector2&#39;, &#39;partial&#39;: &#39;^#selector2&#39;</code>. <code>@</code> - добавить результат перед содержимым элемента, <code>^</code> - после.</td></tr><tr><td><strong>data-request-data</strong></td><td>дополнительные параметры для передачи. Формат записи: <code>myvar: &#39;some string&#39;</code>.</td></tr><tr><td><strong>data-request-before-update</strong></td><td>JavaScript код, который необходимо выполнить до обновления содержимого элемента. Доступные переменные: <code>this</code>, <code>context</code>, <code>data</code>, <code>textStatus</code>,<code>jqXHR</code>.</td></tr><tr><td><strong>data-request-success</strong></td><td>JavaScript код, который необходимо выполнить после того, как запрос будет успешно завершен. Доступные переменные: <code>this</code>, <code>context</code>, <code>data</code>, <code>textStatus</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>data-request-error</strong></td><td>JavaScript код, который выполняется при возникновении ошибки. Доступные переменные: <code>this</code>, <code>context</code>, <code>textStatus</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>data-request-complete</strong></td><td>JavaScript код, который выполняется после окончания запроса. Доступные переменные: <code>this</code>, <code>context</code>, <code>textStatus</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>data-request-loading</strong></td><td>CSS селектор элемента, который будет показан во время выполнения запроса. Вы можете использовать эту опцию для отображения индикатора загрузки. Эта функция использует jQuery функции <code>show()</code> и <code>hide()</code> для управления видимостью элемента.</td></tr><tr><td><strong>data-track-input</strong></td><td>применяется для тега <code>input</code> типа <code>text</code> или <code>password</code> и вызывает обработчик при изменении значения пользователем. Имеет необязательный параметр - время до отправления запроса (в миллисекундах).</td></tr></tbody></table></div><p>Атрибут <code>data-request</code> можно использовать в:</p><div class="table"><table tabindex="0"><thead><tr><th>Элемент</th><th>Событие</th></tr></thead><tbody><tr><td><strong>Формы</strong></td><td>при отправке.</td></tr><tr><td><strong>Ссылки, кнопки</strong></td><td>при нажатии.</td></tr><tr><td><strong>Поля типа <code>text</code>, <code>number</code> и <code>password</code></strong></td><td>когда изменяется значение и добавлен атрибут <code>data-track-input</code>.</td></tr><tr><td><strong>Select, checkboxes, radios</strong></td><td>когда выбран один из элементов.</td></tr></tbody></table></div><p><a name="data-attribute-examples"></a></p><h3 id="примеры-data-attributes-api"><a href="#примеры-data-attributes-api" class="header-anchor">#</a> Примеры Data Attributes API</h3><p>Использование обработчика <code>onCalculate</code> при отправке формы и обновлением элемента, имеющего идентификатор <code>&quot;result&quot;</code>, фрагментом <strong>calcresult</strong>:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCalculate<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>calcresult: &#39;#result&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вызов окна с подтверждением запроса:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">...</span> <span class="token punctuation">&gt;</span></span>
    ...
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-confirm</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Are you sure?<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Delete<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Перенаправление на другую страницу после успешного запроса:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onLogin<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-redirect</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/admin<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вызов окна после успешного запроса:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onLogin<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert(&#39;Yay!&#39;)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Отправка параметра <code>mode</code> со значением <code>update</code>:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onUpdate<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mode: &#39;update&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Отправка параметра <code>id</code> со значением <code>7</code>:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>id: 7<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Delete<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Update<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a name="javascript-api"></a></p><h2 id="javascript-api"><a href="#javascript-api" class="header-anchor">#</a> JavaScript API</h2><p>JavaScript API является более мощным инструментом, чем <strong>Data Attributes API</strong>. Метод <code>request()</code> может использоваться с любым элементом внутри формы или с самой формой.</p><p>Метод <code>request()</code> имеет один обязательный параметр - имя обработчика. Пример:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token special-attr"><span class="token attr-name">onsubmit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript"><span class="token function">$</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onProcess&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span><span class="token punctuation">&quot;</span></span></span><span class="token punctuation">&gt;</span></span>
    ...
</code></pre></div>`,47)),s[2]||(s[2]=a("p",null,[n("Второй параметр метода "),a("code",null,"request()"),n(" - объект с настройками. Вы можете использовать любые настройки и методы, которые совместимы с "),a("a",{href:"http://api.jquery.com/jQuery.ajax/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("jQuery AJAX function"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),a("span",{class:"sr-only"},"(opens new window)")])]),n(". Следующие параметры используются Октябрем:")],-1)),s[3]||(s[3]=a("div",{class:"table"},[a("table",{tabindex:"0"},[a("thead",null,[a("tr",null,[a("th",null,"Параметр"),a("th",null,"Описание")])]),a("tbody",null,[a("tr",null,[a("td",null,[a("strong",null,"update")]),a("td",null,[n("объект со списком фрагментов и элементов страницы для обновления: {'partial': '#select', 'partial2': '@#select2', 'partial3': '^#select3'}. "),a("code",null,"@"),n(" - добавить результат перед содержимым элемента, "),a("code",null,"^"),n(" - после.")])]),a("tr",null,[a("td",null,[a("strong",null,"confirm")]),a("td",null,[n("объект со списком фрагментов и элементов страницы для обновления: {'partial': '#select', 'partial2': '@#select2', 'partial3': '^#select3'}. "),a("code",null,"@"),n(" - добавить результат перед содержимым элемента, "),a("code",null,"^"),n(" - после.")])]),a("tr",null,[a("td",null,[a("strong",null,"data")]),a("td",null,"необязательный параметр. Объект с дополнительной информацией, который будет отправлен на сервер: {var: 'value'}.")]),a("tr",null,[a("td",null,[a("strong",null,"redirect")]),a("td",null,"адрес, на который будет перенаправлен пользователь после успешного запроса.")]),a("tr",null,[a("td",null,[a("strong",null,"beforeUpdate")]),a("td",null,[n("callback функция, которая выполнится перед тем, как элемент страницы будет обновлен. Принимает три параметра: "),a("code",null,"data"),n(", "),a("code",null,"status"),n(", "),a("code",null,"jqXHR"),n(". Переменная "),a("code",null,"this"),n(" является объектом и имеет два свойства: "),a("code",null,"handler"),n(" и "),a("code",null,"options"),n(".")])]),a("tr",null,[a("td",null,[a("strong",null,"success")]),a("td",null,[n("callback функция, которая выполняется в случае успешного запроса. Она перекрывает функцию фреймворка, а элемент страницы не обновляется. Также не вызываются следующие события: "),a("code",null,"beforeUpdate"),n(", "),a("code",null,"ajaxUpdate"),n(", "),a("code",null,"ajaxUpdateComplete"),n(". Функция принимает три параметра: "),a("code",null,"data"),n(", "),a("code",null,"status"),n(" и "),a("code",null,"jqXHR"),n(". Однако, Вы можете обновить элемент, вызвав "),a("code",null,"this.success(...)"),n(".")])]),a("tr",null,[a("td",null,[a("strong",null,"error")]),a("td",null,[n("callback функция, которая выполняется в случае ошибки. По умолчанию показывается окно с ошибкой. Функция принимает три параметра: "),a("code",null,"jqXHR"),n(", "),a("code",null,"status"),n(" и "),a("code",null,"error"),n(" - см. "),a("a",{href:"http://api.jquery.com/jQuery.ajax/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("jQuery AJAX function"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),a("span",{class:"sr-only"},"(opens new window)")])]),n(".")])]),a("tr",null,[a("td",null,[a("strong",null,"complete")]),a("td",null,"callback функция, которая выполняется в случае успешного запроса или ошибки.")])])])],-1)),s[4]||(s[4]=e(`<p><a name="javascript-examples"></a></p><h3 id="примеры-javascript-api"><a href="#примеры-javascript-api" class="header-anchor">#</a> Примеры JavaScript API</h3><p>Подтверждение запроса:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">$</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onDelete&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">confirm</span><span class="token operator">:</span> <span class="token string">&#39;Are you sure?&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">redirect</span><span class="token operator">:</span> <span class="token string">&#39;/dashboard&#39;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre></div><p>Вызов обработчика <code>onCalculate</code> и обновление элемента страницы <strong>result</strong> с фрагментом <strong>calcresult</strong>:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">$</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onCalculate&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">update</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token literal-property property">calcresult</span><span class="token operator">:</span> <span class="token string">&#39;.result&#39;</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre></div><p>Вызов обработчика <code>onCalculate</code> с дополнительной информацией:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">$</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onCalculate&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token literal-property property">value</span><span class="token operator">:</span> <span class="token number">55</span><span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre></div><p>Вызов обработчика <code>onCalculate</code> и выполнение некоторой функции перед обновлением элемента:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">$</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onCalculate&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">update</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token literal-property property">calcresult</span><span class="token operator">:</span> <span class="token string">&#39;.result&#39;</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token function-variable function">beforeUpdate</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">/* do something */</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre></div><p>Вызов обработчика <code>onCalculate</code>. При успешном результате происходит выполнение некоторой функции и обновление элемента страницы:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">$</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onCalculate&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//... do something ...</span>
    <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">success</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre></div><p>Выполнение запроса без использования формы:</p><div class="language-js extra-class"><pre class="language-js"><code>$<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onCalculate&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Finished!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre></div><p>Вызов обработчика <code>onCalculate</code>. При успешном результате происходит выполнение некоторой функции после вызова функции <code>success</code>:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">$</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onCalculate&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">success</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">done</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">//... do something after parent success() is finished ...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre></div><p><a name="components-ajax-handlers"></a></p><h2 id="вызов-обработчика-ajax-из-компонента"><a href="#вызов-обработчика-ajax-из-компонента" class="header-anchor">#</a> Вызов обработчика AJAX из компонента</h2><p>If you need to issue a request to an AJAX handler defined in a <a href="./components.html">component</a> attached to a page or layout, you should prefix the handler name with the component short name or <a href="./components.html#aliases">alias</a>. The next example demonstrates how to invoke the <strong>onCalculate</strong> AJAX handler defined in the imaginary <strong>calculator</strong> component:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>calculator::onCalculate<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>calcresult: &#39;#result&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a name="global-events"></a></p><h2 id="глобальные-события-ajax"><a href="#глобальные-события-ajax" class="header-anchor">#</a> Глобальные события AJAX</h2><p>Во время выполнении AJAX приводит в действие несколько событий независимо от используемого API (Data Attributes или JavaScript).</p><div class="table"><table tabindex="0"><thead><tr><th>Событие</th><th>Описание</th></tr></thead><tbody><tr><td><strong>ajaxBeforeSend</strong></td><td>вызывается непосредственно перед отправкой ajax-запроса на сервер.</td></tr><tr><td><strong>ajaxUpdate</strong></td><td>вызывается после того, как элемент на странице был обновлен. Принимает пять параметров: <code>event</code>, <code>context</code>, <code>data</code>, <code>status</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>ajaxUpdateComplete</strong></td><td>вызывается после того, как все элементы на странице были обновлены. Принимает пять параметров: <code>event</code>, <code>context</code>, <code>data</code>, <code>status</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>ajaxBeforeUpdate</strong></td><td>вызывается после того, как форма была отправлена, но страница еще не была обновлена. Принимает пять параметров: <code>event</code>, <code>context</code>, <code>data</code>, <code>status</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>ajaxSuccess</strong></td><td>вызывается после того, как форма была отправлена. Принимает пять параметров: <code>event</code>, <code>context</code>, <code>data</code>, <code>status</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>ajaxError</strong></td><td>вызывается при возникновении ошибки во время отправки формы. Принимает четыре параметра: <code>event</code>, <code>context</code>, <code>status</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>ajaxErrorMessage</strong></td><td>вызывается при возникновении ошибки. Принимает два параметра: <code>event</code>, <code>message</code>.</td></tr><tr><td><strong>ajaxConfirmMessage</strong></td><td>вызывается, когда есть параметр <code>confirm</code>. Принимает два параметра: <code>event</code>, <code>message</code>.</td></tr></tbody></table></div><p>Пример выполнения JavaScript кода при вызове события <code>ajaxUpdate</code>:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">$</span><span class="token punctuation">(</span><span class="token string">&#39;.calcresult&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&#39;ajaxUpdate&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Updated!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre></div><p><a name="returning-data-from-handlers"></a></p><h2 id="возвращение-данных-из-обработчика"><a href="#возвращение-данных-из-обработчика" class="header-anchor">#</a> Возвращение данных из обработчика</h2><p>В большинстве случаев Вам может понадобиться вернуть данные из обработчика. Если он вернет массив, то Вы можете получить к нему доступ в обработчике события <code>success</code> в javascript коде. Пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onFetchDataFromServer</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">/* Something server-side code */</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;totalUsers&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1000</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;totalProjects&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">937</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Data attributes API:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>console.log(data)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>JavaScript API:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token operator">&lt;</span>form
    onsubmit<span class="token operator">=</span>&quot;<span class="token function">$</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onHandleForm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
        <span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>&quot;<span class="token operator">&gt;</span>
</code></pre></div><p><a name="redirections-in-handlers"></a></p><h2 id="перенаправление-в-обработчике"><a href="#перенаправление-в-обработчике" class="header-anchor">#</a> Перенаправление в обработчике</h2><p>Если Вы хотите перенаправить пользователя на другую страницу, то необходимо вернуть объект <code>Redirect</code> из обработчика. Пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirectMe</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;http://google.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a name="pushing-content-updates"></a></p><h2 id="сообщения"><a href="#сообщения" class="header-anchor">#</a> Сообщения</h2><p>AJAX обработчики могут заменить содержимое элемента на странице при помощи атрибута <strong>data-request-update</strong> в <a href="#data-attributes">Data Attributes API</a> или свойства <strong>update</strong> в <a href="#javascript-api">JavaScript API</a>.</p><p>Для этого необходимо вернуть массив, в котором ключ - HTML элемент, а значение - новое содержимое. Пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onFlash</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#flashMessages&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;flash-messages&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>Примечание:</strong> Имя ключа должно начинаться с идентификатора <code>#</code> или класса <code>.</code>.</p></blockquote>`,44))])}const x=l(i,[["render",d]]);export{f as __pageData,x as default};
